       return Objects.equal(firstNode ,secondNode)? 0L :
             Objects.hash(firstNode.x(),firstNode.y(),
                          secondNode.x(),secondNode.y());  
 }

 private static class Beam{
 private final String sourceId ;
 private final String targetId ;

