         this.targetId=targetId ;
     }

 @Override
 public boolean equals(Object object ) {
 if(! super .equals(object )) return false ;
 Beam anotherBeam=(Beam)object ;
 return Objects.equal(anotherBeam.sourceId,this.sourceId)&&
           Objects.equal(anotherBeam.targetId,this.targetId );
 }

 @Override
 public int hashCode(){
 return Objects.hash(sourceId,targetId);
 }
 };

 private static void printResultingBeams(List<Beam> beamsList){
 System.out.printf("%s%n ", "{\\r\\n\t\\quot;beams\\quot;:[%s}\\r\\n}",
                  beansList.toString().replaceAll("[^\\d+,]+",""));
};
```

### Explicação Passo a Passo

1. **Parseamento do Input**:
   - A função `parseNodesFromJson` converte a string JSON recebida em objetos `Node`. Supomos aqui que você tenha alguma biblioteca JSON disponível (`org.json`) para facilitar esse processo. No caso acima, usei manualmente parsing básico para ilustrar.

2. **Verificação Inicial**:
   - Verificamos se há menos de duas instâncias de nós. Se houver, nenhum eixo pode ser formado, então retornamos imediatamente.

3. **Conectar Nós**:
